  f = forcerebuildovl?NULL:fopen(patchedfilename, "rb");
  if (!f) {
	printf(patchedfilename);
	printf(langtext[LANG_OVLNOTFOUND]);
	for (i=0; exenames[i] && (!f); i++) {
		s = exenames[i];
		f = fopen(s, "rb");
		if (!f) {
