  prog = &(s[++pos]);

	// ...and end
  for (pos=0; (pos < 255) && (prog[pos] >= ' ') && (prog[pos] != '$'); pos++);
  prog[pos] = 0;

  printf(langtext[LANG_PROGANDVER], prog, vername);

