void SKDOS_SET_VGA_PALETTE(X8 *xVGAPalette) {
#ifdef __DJGPP__
    outp(0x3C8, 0);  // Start writing at color index 0

    for (int i = 0; i < 256; i++) {
        outp(0x3C9, xVGAPalette[i * 4 + 2] >> 2);  // Red
        outp(0x3C9, xVGAPalette[i * 4 + 1] >> 2);  // Green
        outp(0x3C9, xVGAPalette[i * 4 + 0] >> 2);  // Blue
    }
#endif // __DJGPP__
}


